    26	// Map ENDTOEND event format to RawEventInput
    27	function mapToRawEventInput(event: any, source: string): RawEventInput {
    28	  return {
    29	    source,
    30	    source_id: event.id,
    31	    title: event.title,
    32	    description: event.description || '',
    33	    start_date: event.date,
    34	    start_time: event.time,
    35	    end_date: event.date,
    36	    end_time: event.time,
    37	    venue_name: event.venue,
    38	    venue_city: event.area || 'Stockholm',
    39	    venue_address: event.address || '',
    40	    venue_lat: event.lat || null,
    41	    venue_lng: event.lng || null,
    42	    category: event.category || 'culture',
    43	    url: event.url || '',
    44	    image_url: event.image_url || event.imageUrl || null,
    45	    price_info: event.price_info || event.priceInfo || null,
    46	    promoter: event.promoter || null,
    47	    organizer: event.organizer || null,
    48	    accessibility: event.accessibility || null,
    49	    age_restriction: event.age_restriction || event.ageRestriction || null,
    50	    tags: event.tags || [],
    51	    raw_data: event,
    52	  };
    53	}
    54	
    55	// Queue events from any source
    56	async function queueEvents(events: any[], source: string): Promise<number> {
    57	  let queued = 0;
    58	  for (const event of events) {
    59	    try {
    60	      const rawEvent = mapToRawEventInput(event, source);
    61	      await rawEventsQueue.add('process-raw-event', rawEvent, {
    62	        jobId: `${source}:${event.id}`,
    63	      });
    64	      queued++;
    65	    } catch (err) {
    66	      console.error(`[${source}] Failed to queue event ${event.id}:`, err);
    67	    }
    68	  }
    69	  return queued;
    70	}
    71	
    72	// Run a single source
    73	export async function runSource(
    74	  name: string,
    75	  fetchFn: () => Promise<any[]>,
    76	  options?: { filterFn?: (e: any) => boolean }
    77	): Promise<SourceResult> {
    78	  console.log(`[sources] Running source: ${name}`);
    79	  const result: SourceResult = {
    80	    source: name,
    81	    eventsQueued: 0,
    82	    eventsFound: 0,
    83	    errors: [],
    84	    status: 'success',
    85	  };
    86	
    87	  try {
    88	    const events = await fetchFn();
    89	    result.eventsFound = events.length;
    90	    
    91	    const filtered = options?.filterFn 
    92	      ? events.filter(options.filterFn) 
    93	      : events;
    94	    
    95	    if (filtered.length < events.length) {
    96	      console.log(`[${name}] Filtered ${events.length - filtered.length} events`);
    97	    }
    98	    
    99	    result.eventsQueued = await queueEvents(filtered, name);
   100	    
   101	    if (result.eventsQueued === 0 && result.eventsFound > 0) {
   102	      result.status = 'partial';
   103	    }
   104	  } catch (err: any) {
   105	    result.errors.push(err.message || String(err));
   106	    result.status = 'fail';
   107	    console.error(`[${name}] Error:`, err);
   108	  }
   109	
   110	  return result;
   111	}
